CREATE TABLE simulated_credit_profile(user_id BIGINT PRIMARY KEY,document_number VARCHAR(8) NOT NULL,display_name VARCHAR(120) NOT NULL,monthly_income DECIMAL(18,2) NOT NULL,monthly_expenses DECIMAL(18,2) NOT NULL,monthly_obligations DECIMAL(18,2) NOT NULL,employment_months INT NOT NULL,active_obligations INT NOT NULL,payment_history_score INT NOT NULL,delinquency_alerts INT NOT NULL);
